def _raw_to_rgba(raw_bytes, w, h, ink=(18, 18, 18)):
    # Convert raw MSB bytes (1 = black) to RGBA with alpha
    inv = bytes([~b & 0xFF for b in raw_bytes])
    img1 = Image.frombytes('1', (w, h), inv)
    # Convert 1-bit (0=black, 255=white) to RGBA where black has ink color and white is transparent
    rgba = Image.new('RGBA', (w, h), (0, 0, 0, 0))
    alpha = ImageOps.invert(img1.convert('L'))
    color_fill = Image.new('RGBA', (w, h), (ink[0], ink[1], ink[2], 255))
    rgba.paste(color_fill, (0, 0), alpha)
    return rgba

